package android.view;import java.util.*;public class View {public static final int VISIBLE=0,GONE=8;public interface OnClickListener{void onClick(View v);}public final android.content.Context context;public final Map<Integer,View> children=new HashMap<Integer,View>();public OnClickListener listener;public int visibility=VISIBLE;public boolean enabled=true,attached=true;public CharSequence description;public ViewGroup.LayoutParams layout=new ViewGroup.LayoutParams();public View(android.content.Context c){context=c;}public View findViewById(int id){return children.get(id);}public android.content.res.Resources getResources(){return context.getResources();}public ViewGroup.LayoutParams getLayoutParams(){return layout;}public void setLayoutParams(ViewGroup.LayoutParams p){layout=p;}public void setOnClickListener(OnClickListener l){listener=l;}public boolean performClick(){if(listener==null)return false;listener.onClick(this);return true;}public void setVisibility(int n){visibility=n;}public int getVisibility(){return visibility;}public boolean isEnabled(){return enabled;}public void setContentDescription(CharSequence s){description=s;}public Object getWindowToken(){return attached?this:null;}}
